#include <stdio.h>
#include <stdlib.h>

#define INF (1LL << 60)

static int compare_ints(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int N, K;
    if (scanf("%d %d", &N, &K) != 2) return 0;

    int *T = malloc((size_t)N * sizeof(int));
    for (int i = 0; i < N; i++) scanf("%d", &T[i]);
    qsort(T, N, sizeof(int), compare_ints);

    int L = N - K;
    long long *prev2 = malloc((size_t)(K + 1) * sizeof(long long));
    long long *prev = malloc((size_t)(K + 1) * sizeof(long long));
    long long *curr = malloc((size_t)(K + 1) * sizeof(long long));

    for (int j = 0; j <= K; j++) {
        prev2[j] = INF;
        prev[j] = INF;
    }
    prev[0] = 0;  /* DP for the first zero elements */

    for (int i = 1; i <= L; i++) {
        for (int j = 0; j <= K; j++) curr[j] = prev[j];

        if (i >= 2) {
            long long diff = (long long)T[i - 1] - T[i - 2];
            long long cost = diff * diff;

            for (int j = 1; j <= K; j++) {
                if (prev2[j - 1] != INF &&
                    prev2[j - 1] + cost < curr[j]) {
                    curr[j] = prev2[j - 1] + cost;
                }
            }
        }

        long long *tmp = prev2;
        prev2 = prev;
        prev = curr;
        curr = tmp;
    }

    printf("%lld\n", prev[K]);

    free(T);
    free(prev2);
    free(prev);
    free(curr);
    return 0;
}
